INSERT INTO `Card_Info` (`ID`, `SuitID`, `Name`, `Description`) VALUES
(1,1,'Bộ thẻ huyệt ma kiến','Vô số dũng sĩ từ mọi nơi đều đang tập hợp tại đây, cánh rừng ma quái.Mọi người cần phải tìm ra nơi cư ngụ của loài kiến ma &quot;Huyệt ma kiến&quot; . Qua những trận chiến gian nan, cuối cùng họ cũng hạ được nữ vương kiến và lấy được bộ thẻ phép thuật!'),
(2,1,'Bộ thẻ vương thành gà','Sau khi hạ được Quốc vương xấu tính của vương thành gà, các dũng sĩ đã chế tạo thành công bộ thẻ phép thuật nhưng chẳng may Mathias đã cướp chúng đi.Giờ mọi người phải cùng hợp sức để cướp lại bộ thẻ!'),
(3,1,'Bộ thẻ bộ lạc tà thần','Tương truyền rằng có một bộ thẻ đã ghi lại những bí mật kinh thiên động địa của cây thương cổ đang bị lưu lạc trong một bộ lạc bị khống chế bởi thế lực đen tối. Hãy mau đến đó tìm lại bộ thẻ này!'),
(4,1,'Bộ thẻ pháo đài hắc ám','Trong pháo đài hắc ám,không hiểu sao luôn phát ra  thứ ánh sáng lấp lánh, thì ra đó là ánh sáng của bộ thẻ thần bí.Nếu lấy lại được và sử dụng đúng cách sẽ giúp pháo đài trở lại sự yên bình.'),
(5,0,'Bộ thẻ vũ khí thần bí','Các dũng sĩ đã tìm thấy trong rừng sâu dấu tích 4 loại vũ khí.Tương truyền do không thể khống chế sức mạnh nên vũ khí đã bị tiêu hủy.Nếu như bây giờ chúng ta tìm ra 4 loại thẻ đặc biệt thì có thể triệu hồi sức mạnh của vũ khí.'),
(6,1,'Bộ thẻ Goblin','Tà Diệm Long cuối cùng đã bị hạ, hãy xem có thứ gì rơi ra kìa.Các dũng sĩ chạy đến xem thì phát hiện ra bộ thẻ Goblin ghi cháp những bí mật. Nhưng đúng lúc này xào huyệt sụp đổ, các dũng sĩ đã không thể quay trở ra.'),
(7,1,'Bộ thẻ giải cứu gà con','Giải cứu những chú gà vàng thật xinh xắn sẽ được tặng những bộ thẻ thần bí. Nhưng không chỉ có 1 con gà mái xấu xí, các dũng sĩ, ãy mau lên đường cứu những chú gà vàng nào!'),
(8,1,'Bộ thẻ Đấu trường gà','Vương quốc gà đã tổ chức thành công đại hội thể thao đầu tiên. Và lần này cũng đặc biệt sản xuất bộ thẻ Đấu trường gà. Ngoài việc dùng làm kỹ niệm, bộ thẻ còn mang đến cho bạn sự may mắn.Bạn có phải là người của chiến thắng không?'),
(9,0,'Bộ thẻ Ngũ Thần Binh','Ngũ đại thần đang cai quản và giữ thế cân bằng cho thế giới, thế nhưng vũ khí họ sử dụng lại lưu lạc trong nhân gian. Tương truyền nếu tập hợp được cùng lúc 5 vũ khí này sẽ có sức mạnh vô song!'),
(10,1,'Bộ thẻ Vòng xoáy thời gian','Vậy là tất cả những chiến tranh đều do bác học Vẹt mà ra. Các chiến sỹ trận mạc đã tặng những dũng sỹ của chúng ta thẻ bài quý được cất giữ đã lâu nhằm tỏ lòng biết ơn.'),
(11,1,'Thẻ Đấu Trường Dũng Sĩ','Nghe nói trong đấu trường xưa có 1 bộ thẻ Đấu Trường Dũng Sĩ có uy lực rất mạnh, không thể để chúng rơi vào tay thế lực đen tối, các dũng sĩ hãy bắt đầu cuộc hành trình của mình'),
(12,0,'Bộ Thẻ Truyền Thuyết Khai Hoang','Vũ khí ẩn chứa lý tưởng và quá khứ của dũng sĩ. Họ đã chế tạo bộ thẻ bài này để kỷ niệm thời thanh xuân của mình, sở hữu có nó sẽ nhận được chúc phúc.'),
(13,0,'Bộ Thẻ Đại Sư Vũ Khí','Thần khí có sức mạnh to lớn, sở hữu chúng sẽ trở thành nhân tài kiệt xuất. Chủ nhân thần khí chế tạo bộ thẻ bài này để tặng cho người có duyên, mong rằng có thể giúp họ trưởng thành!'),
(14,0,'Bộ Thẻ Thần Vực','Sau cuộc chiến phong ấn ma, bộ thẻ Thần Vực lưu lạc nhân gian, bị tà ma cướp mất, chúng ẩn nấp khắp nơi để chờ thời cơ phản công. Các dng sĩ vẫn luôn tìm kiếm bộ thẻ, hy vọng dập tắt âm mưu của chúng.'),
(15,0,'Bộ Thẻ May Mắn','Dù cuộc sống vẫn luôn tràn ngập phiền não, nhưng chỉ cần mỉm cười may mắn sẽ đến. Bộ thẻ bài tặng may mắn cho dũng sĩ, nỗi buồn sẽ kết thúc từ đây!');
