(1774,'Thức Tỉnh 3-Màn Đêm Bảo Vệ',0,0,'1716,1772,3780,','Kháng Bỏng +12%; Bảo vệ tất cả đồng đội trong màn đêm, hiệu quả Giảm Thương của bản thân tăng 30%, giúp đồng đội chịu 50% sát thương, duy trì 2 turn. Có thể nuốt Lửa Hận Thù đang tồn tại, khiến đồng đội được bảo vệ nhận Giáp Đen Minotaure và Búa Bạc Minotaure, duy trì 2 turn.',3,-1,20,118,'beatD','',1400,3,0,-1),
(1775,'Thức Tỉnh 3-Ban Ngày Xâu Xé',0,0,'3781,1773,','Kháng Bỏng +12%; Ban ngày xâu xé điên cuồng, gây hiệu quả Xuất Huyết cho địch trong cự ly 300, khiến địch mỗi turn mất 10% HP, duy trì 3 turn. Có thể nuốt Lửa Oán Giận đang có, Xuất Huyết sẽ kèm hiệu quả Cấm Trị Liệu và Cấm Bay (Có hiệu lực trong PVP).',3,-1,20,119,'beatA','',1400,3,2,-1),
(1776,'Thức Tỉnh 3-Giáp Đen Minotaure',0,0,'3782,','Kháng Xuyên Giáp +10%; Mỗi khi chịu sát thương đạn pháo, Giáp Minotaure giảm sát thương bằng 4% HP hiện tại.',3,-1,0,120,'','',0,0,0,10000),
(1777,'Thức Tỉnh 3-Búa Bạc Minotaure',0,0,'3783,3784,1834,','Kháng Xuyên Giáp +10%; Búa Minotaure cực nặng gây thêm sát thương cho địch ở địa hình thấp hơn, mỗi 100 pixel tăng 30% sát thương, tối đa tăng 150% sát thương. Với địch ở địa hình cao hơn, tạo hiệu quả giảm thương, mỗi 100 pixel giảm 20% sát thương, tối đa giảm 60% sát thương (Có hiệu lực trong PVP).',3,-1,0,121,'','',0,0,2,10000),
