(351,0,'Dung luyện lần đầu','<crĐá cường hóa,chu tước,thanh long,bạch hổ,bao tay, nhẫn cr>đều có thể <crdung luyệncr>,cần chú ý vật phẩm phải<cr cùng cấp,cùng têncr> mới có thể dung luyện.','',10,70,'350,','0,',0,0,1,1,1000,2000,0,0,0,0,0,0,0,0.00,'2000-01-01 00:00:00.000','2050-01-01 23:59:59.000',1,0,0,0,NULL,0,0),
(352,0,'Chứng nhận danh dự-Huân chương','<crHuân chươngcr> là một vật phẩm hiếm trong game,chỉ khi hoàn thành một số nhiệm vụ hằng ngày,nhiệm vụ sự kiện mới nhận được phần thưởng huân chương. Dùng huân chương để vào  shop,<crtrong khu vự huân chương để đổi lấy đá cường hóa, đá hợp thành, vũ khí và trang bị hiếmcr>!','',10,70,'350,','0,',0,0,1,1,1000,2000,0,0,0,0,0,0,0,0.00,'2000-01-01 00:00:00.000','2050-01-01 23:59:59.000',1,0,0,0,NULL,0,0),
