(385,1,'Giao hữu kết bạn Ⅳ','Trong danh sách bạn bè mạng xã hội, mời những bạn chưa từng chơi gunny tham gia và khi bạn bè đạt cấp 10, xem như thành công, bạn sẽ nhận được bức thư "thư phản hồi", sử dụng vật phẩm này xem như hoàn thành nhiệm vụ!','',5,70,'384,','0,',4,0,1,1,1500,2000,0,0,0,0,0,0,0,2000.00,'2000-01-01 00:00:00.000','2000-01-01 00:00:00.000',2,0,0,0,NULL,0,0),
(393,0,'Đại chiến rồng!Thăm dò','Pháo đài hắc ám tọa lạc trên 1 hòn đảo đầy yêu khí. Truyền thuyết tại đây còn 1 con rồng cực lớn, đến đây phải thăm dò trước và phải hết sức cẩn thận!','',20,70,'0,','394,',0,0,1,1,10000,500,0,0,0,0,0,0,0,7000.00,'2000-01-01 00:00:00.000','2050-01-01 23:59:59.000',2,0,0,0,NULL,0,0),
(439,0,'Đấu trường gà! Tìm hiểu','Để chúc mừng hòa bình, quốc vương gà tổ chức đại hội thể thao Đấu trường gà lần 1. Lần này sẽ do em họ của quốc vương là Grace tuyên bố chỉ có chiến thắng mới có phần thưởng.Bây giờ bạn hãy cải trang thành thần dân gà để tham dự nhé.','',20,70,'0,','440,',0,0,1,1,10000,500,0,0,0,0,0,0,0,7000.00,'2000-01-01 00:00:00.000','2050-01-01 23:59:59.000',2,0,0,0,NULL,0,0),
