(1599,2,'Món quà cho người thắng trận','Trong chiến đấu thắng trận có xác suất nhận được trận hồn,<cr thu thập 5 trận hồncr> có thể nhận được <crmũi khoancr>,phần thưởng dành cho người chiến thắng!','',10,70,'1598,','0,',0,1,1,1,15000,2000,0,0,0,0,0,0,0,70000.00,'2000-01-01 00:00:00.000','2050-01-01 23:59:59.000',1,0,0,0,NULL,0,0),
(1601,3,'Thầy trò hiệp lực (đệ tử)','Có sư phụ rồi thì phải cùng sư phụ chiến đấu để nhận nhiều phần thưởng hơn.Cùng sư phụ hoàn thành 8 trận "thầy trò chiến" là hoàn thành nhiệm vụ nhận thưởng','',1,19,'0,','0,',5,1,1,1,2000,500,0,0,0,0,0,0,0,0.00,'2011-09-08 00:00:00.000','2011-09-13 23:59:59.000',1,0,0,0,NULL,0,0),
