(1054,3,'Công chúa sao rồi-Phá giải thần chú','Một ngày nọ, công chúa "Lộ Lộ" vẫn đi trộm thức ăn như thường lệ, khi nàng đang thích thú thì một bóng đen chớp ngang đỉnh đầu, thoáng chốc Công Chúa đã mê man. Quốc Vương lo lắng triệu tất cả thầy thuốc giỏi vào chữa bệnh cho Công Chúa, nhưng dù là Tô Đơn Hồng hay Địa Câu Du, thử qua nhiều cách, Công Chúa vẫn bất tỉnh. Cuối cùng một ông lão nói với Quốc Vương rằng Công Chúa đã bị Ác Long ếm bùa ma, chỉ có Máu ác long mới có thể giải bùa. Thế là Quốc Vương triệu tập dũng sĩ đi tiêu diệt Ác Long. Đánh bại Cướp biển lạc đường có thể nhận được "Kiếm Dũng sĩ", giúp chiến đấu tốt hơn.','',8,70,'0,','0,',0,0,1,1,10000,5000,0,0,0,0,0,0,0,70000.00,'2011-11-29 00:00:00.000','2011-12-05 23:59:59.000',2,0,0,0,NULL,0,0),
(1055,3,'24 tiết khí-Đại Tuyết','Một trong 24 khí tiết, "Đại Tuyết", nghe tên là có thể đoán được, vào thời điểm này rơi rất nhiều tuyết. (Hoạt động kết thúc vào ngày 12 tháng 12)','',8,70,'0,','0,',0,1,1,1,2500,1500,0,0,0,0,0,0,0,70000.00,'2011-12-06 00:00:00.000','2011-12-12 23:59:59.000',2,0,0,0,NULL,0,0),
(1056,3,'Xe tuyết Sulan','Khi dũng sĩ tiến vào thành đài cứu thế, Sulan đã phun lửa sát thương dũng sĩ, các dũng sĩ làm sao để vượt qua cửa ải này. Trời cao vẫn còn công bằng, tuyết rơi rất nhiều làm suy yếu lửa. Hỡi các dũng sĩ, hãy cầm vũ khí và chiến đấu với Sulan nào! (Hoạt động kết thúc vào ngày 12 tháng 12).','',8,70,'0,','0,',0,1,1,1,2500,3000,0,0,0,0,0,0,0,70000.00,'2011-12-06 00:00:00.000','2011-12-12 23:59:59.000',2,0,0,0,NULL,0,0),
(1057,3,'Sư đồ đồng lòng, vượt mọi thử thách (Sư)','Hãy chiến đấu cùng đồ đệ thân yêu nhé, dưới sự chỉ dạy của bạn, nhất định có một ngày đồ đệ sẽ trở thành dũng sĩ xuất chúng. (Sự kiện kết thúc vào ngày 12 tháng 12)','',20,70,'0,','0,',5,1,1,3,2500,600,0,0,0,0,0,0,0,70000.00,'2011-12-06 00:00:00.000','2011-12-12 23:59:59.000',2,0,0,0,NULL,0,0),
(1058,3,'Sư đồ đồng lòng, vượt mọi thử thách (Đệ)','Hãy chiến đấu cùng sư phụ kính yêu nào, dưới sự hướng dẫn của sư phụ, nhất định có một ngày bạn sẽ trở thành dũng sĩ xuất chúng. (Sự kiện kết thúc vào ngày 12 tháng 12)','',8,19,'0,','0,',5,1,1,3,2000,500,0,0,0,0,0,0,0,70000.00,'2011-12-06 00:00:00.000','2011-12-12 23:59:59.000',2,0,0,0,NULL,0,0),
(1078,3,'24 tiết khí-Tiểu Hàn','Tiểu Hàn là tiết khí thứ 23, từ ngày 5-7 tháng 1, đánh dấu bước vào những ngày lạnh nhất trong năm. (Hoạt động kết thúc ngày 9/1)','',8,70,'0,','0,',0,1,1,1,2500,1500,0,0,0,0,0,0,0,70000.00,'2012-01-03 00:00:00.000','2012-01-09 23:59:59.000',2,0,0,0,NULL,0,0),
(1079,3,'Ngày xuân lãng mạn','Ánh mặt trời mùa xuân trời ấm áp, lòng người thoải mái, chúng ta hãy cùng nhau chiến đấu, cùng nhau đón mừng mùa xuân. (Hoạt động kết thúc ngày 16/1)','',8,70,'0,','0,',2,1,1,1,6620,1314,0,0,0,0,0,0,0,70000.00,'2012-01-10 00:00:00.000','2012-01-16 23:59:59.000',2,0,0,0,NULL,0,0),
(1080,3,'Tình nghĩa sư đồ (Sư)','Cùng chiến đấu với đồ đệ, dưới sự dẫn dắt của bạn, nhất định đồ đệ sẽ có nhành thành tài! (Hoạt động kết thúc ngày 16/1)','',20,70,'0,','0,',5,1,1,3,2500,600,0,0,0,0,0,0,0,70000.00,'2012-01-10 00:00:00.000','2012-01-16 23:59:59.000',2,0,0,0,NULL,0,0),
